1	use crate::budget::BudgetSummary;
2	use crate::error::DomainError;
3	use crate::hints::Hint;
4	use crate::idempotency::PartialSuccess;
5	use crate::json;
6	use crate::kv::KvItem;
7	use crate::pipeline::Pipeline;
8	use crate::provenance::ProvenanceBlock;
9	use crate::recovery::RecoveryHint;
10	use crate::section::{Section, SectionBody};
11	use crate::status::StatusResponse;
12	use crate::toon::{ListRef, ToonDocument, Value};
13	
14	/// The serialisation format for `AgentResponse::render`.
15	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
16	#[non_exhaustive]
17	pub enum OutputFormat {
18	    /// Plain-text TOON / kv format. Default.
19	    #[default]
20	    Text,
21	    /// Compact JSON object.
22	    Json,
23	}
24	
25	/// Default per-cell truncation limit used by [`AgentResponse::new`].
26	pub const DEFAULT_TRUNCATE_CELLS: usize = 200;
27	
28	/// Builder for an agent-facing response: an ordered list of [`Section`]s, an optional error, budget report and
29	/// provenance block, hints and recovery hints.
30	///
31	/// It is the one composer and the one writer. Every outcome michi renders is a part of it: a [`DomainError`] is its
32	/// error block ([`error`](Self::error)), and a [`PartialSuccess`], [`StatusResponse`], [`Pipeline`] or already-done
33	/// report becomes sections ([`partial_success`](Self::partial_success), [`status`](Self::status),
34	/// [`pipeline`](Self::pipeline), [`already_done`](Self::already_done)). Their hints and recovery hints join the
35	/// response's one `help` and one `recovery` block, so a batch with results, per-op outcomes and an error is one valid
36	/// document on every surface. Each type's own `render` is this writer too.
37	#[derive(Debug, Clone)]
38	#[non_exhaustive]
39	pub struct AgentResponse {
40	    /// The type name given to [`new`](Self::new): it names the sections that [`items`](Self::items) and
41	    /// [`kv_items`](Self::kv_items) append, and the empty list an untouched response renders.
42	    name: String,
43	    /// Per-cell cap for every `Toon` section, set with [`truncate_cells_at`](Self::truncate_cells_at).
44	    max_cell_len: usize,
45	    /// The caller's instruction for getting a cut cell in full, set with [`truncation_hint`](Self::truncation_hint).
46	    truncation_hint: Option<String>,
47	    /// Every block, in call order. The one place a response keeps its body.
48	    sections: Vec<Section>,
49	    /// Response-level budget report, set with `budget()`.
50	    budget: Option<BudgetSummary>,
51	    /// Response-level provenance block, set with `provenance()`.
52	    provenance: Option<ProvenanceBlock>,
53	    /// The error this response reports, set with `error()`: rendered first, as the root `error`, `message`, `causes`
54	    /// and `exit_code` keys.
55	    error: Option<DomainError>,
56	    hints: Vec<Hint>,
57	    recovery: Vec<RecoveryHint>,
58	    is_error: bool,
59	    human_content: Option<String>,
60	}
61	
62	impl AgentResponse {
63	    /// Create a new, empty response for the given type name. The name labels the sections that
64	    /// [`items`](Self::items) and [`kv_items`](Self::kv_items) add. A response that never gets a section, budget or
65	    /// provenance renders `name: []` and `totalCount: 0`, the definitive empty list.
66	    pub fn new(type_name: impl Into<String>) -> Self {
67	        Self {
68	            name: type_name.into(),
69	            max_cell_len: DEFAULT_TRUNCATE_CELLS,
70	            truncation_hint: None,
71	            sections: Vec::new(),
72	            budget: None,
73	            provenance: None,
74	            error: None,
75	            hints: Vec::new(),
76	            recovery: Vec::new(),
77	            is_error: false,
78	            human_content: None,
79	        }
80	    }
81	
82	    /// Append a TOON list section named for the response's type: shorthand for
83	    /// `section(Section::toon(name, fields, rows))`. Every call adds a section, rendered in call order.
84	    ///
85	    /// Sections are root keys, and this shorthand gives each the same name, so for one list per response only: a
86	    /// second `items()` call repeats the key `name`, and the response renders the `toon_validation_failed` error
87	    /// naming it (and `is_error()` is true) instead of invalid TOON. Mixing with [`kv_items`](Self::kv_items) works
88	    /// while no KV key equals the type name. For several lists, give each its own name with
89	    /// `.section(Section::toon(distinct_name, ..))`. To report a total, build the section yourself and set
90	    /// [`Section::total_count`].
91	    #[must_use]
92	    pub fn items(self, rows: Vec<Vec<Value>>, fields: &[&str]) -> Self {
93	        let name = self.name.clone();
94	        self.section(Section::toon(name, fields.iter().map(|s| (*s).to_string()).collect(), rows))
95	    }
96	
97	    /// Append a TOON list section for a cut list, in one call. The rows are `outcome.kept`, each turned into a row by
98	    /// `row`; the section's total is `outcome.total_before`; and, only when something was cut,
99	    /// [`TruncationOutcome::hint`](crate::truncation::TruncationOutcome::hint) (`showing {kept} of {total}; {guidance}`)
100	    /// is appended to the hints. michi builds the rows from the outcome itself, so the list's `[N]`, its `totalCount`
101	    /// and the `help[]` line all describe the same cut.
102	    ///
103	    /// `totalCount` renders only when `total_before` exceeds the rows kept.
104	    ///
105	    /// ```
106	    /// use michi_core::toon::Value;
107	    /// use michi_core::{truncate_by_count, AgentResponse, OutputFormat};
108	    ///
109	    /// let outcome = truncate_by_count(vec![1, 2, 3, 4], 2);
110	    /// let r = AgentResponse::new("issues").truncated_section(
111	    ///     "issues",
112	    ///     vec!["n".into()],
113	    ///     &outcome,
114	    ///     |n| vec![Value::Int(*n)],
115	    ///     "pass --limit 4",
116	    /// );
117	    /// assert_eq!(
118	    ///     r.render(OutputFormat::Text),
119	    ///     "issues[2]{n}:\n  1\n  2\ntotalCount: 4\nhelp[1]: showing 2 of 4; pass --limit 4"
120	    /// );
121	    /// ```
122	    #[must_use]
123	    pub fn truncated_section<T>(
124	        mut self,
125	        name: impl Into<String>,
126	        fields: Vec<String>,
127	        outcome: &crate::truncation::TruncationOutcome<T>,
128	        row: impl FnMut(&T) -> Vec<Value>,
129	        guidance: impl Into<String>,
130	    ) -> Self {
131	        let rows = outcome.kept.iter().map(row).collect();
132	        if let Some(hint) = outcome.hint(guidance) {
133	            self.hints.push(hint);
134	        }
135	        self.section(Section::toon(name, fields, rows).total_count(Some(outcome.total_before)))
136	    }
137	
138	    /// Append a KV section named for the response's type: shorthand for `section(Section::kv(name, items))`. The name
139	    /// is not printed for a KV body. Every call adds a section, but the item keys are root keys: two calls sharing a
140	    /// key render the `toon_validation_failed` error naming it. See [`items`](Self::items); for several KV sections
141	    /// use `.section(Section::kv(name, ..))` and keep the keys distinct.
142	    #[must_use]
143	    pub fn kv_items(self, items: Vec<KvItem>) -> Self {
144	        let name = self.name.clone();
145	        self.section(Section::kv(name, items))
146	    }
147	
148	    /// Append a section. Sections render in call order, the one place a response keeps its body: the caller owns
149	    /// ordering.
150	    ///
151	    /// The response's cell cap ([`truncate_cells_at`](Self::truncate_cells_at)) and truncation hint apply to every
152	    /// `Toon` body. A section's `totalCount` comes from [`Section::total_count`]. Each section is a root key of the
153	    /// document, so names must be distinct (see [`Section`]).
154	    #[must_use]
155	    pub fn section(mut self, section: Section) -> Self {
156	        self.sections.push(section);
157	        self
158	    }
159	
160	    /// Attach the response-level budget report; one per response, a second call replaces the first. It renders as a
161	    /// `budget:` block after the last section (see [`BudgetSummary`] for what it carries), and the per-section
162	    /// roll-up appears only when the response has two or more sections. michi renders the report; it never computes
163	    /// it.
164	    ///
165	    /// A response with a budget or provenance but no section has no body of its own: the empty `type: []` line that
166	    /// an untouched response renders is left out.
167	    #[must_use]
168	    pub fn budget(mut self, budget: BudgetSummary) -> Self {
169	        self.budget = Some(budget);
170	        self
171	    }
172	
173	    /// Attach the response-level provenance block; one per response, a second call replaces the first. It renders as
174	    /// a `provenance:` block after `budget:` (see [`ProvenanceBlock`]).
175	    #[must_use]
176	    pub fn provenance(mut self, provenance: ProvenanceBlock) -> Self {
177	        self.provenance = Some(provenance);
178	        self
179	    }
180	
181	    /// Report `error` as this response's error; one per response, a second call replaces the first. It renders
182	    /// first, before every section, as the root keys `error: <code>`, `message: …`, `causes[N]: …` (when there are
183	    /// causes) and `exit_code: 1`, the same lines [`DomainError::render`] writes. Its hints lead the response's one
184	    /// `help` block and its recovery hint leads the one `recovery` table. The response is an error on every surface.
185	    ///
186	    /// In JSON the error is one object, `"error": {"code", "message", "causes", "retryable"}`, next to the response's
187	    /// `hints` and `recovery` arrays: the only error shape michi writes. A section that fails validation writes an
188	    /// `error` key too, so a response holding both renders the `toon_validation_failed` error for the repeated key.
189	    ///
190	    /// ```
191	    /// use michi_core::{AgentResponse, DomainError, ErrorCode, OutputFormat};
192	    ///
193	    /// let e = DomainError::new(ErrorCode::NotFound, "no issue 7").hint("list issues first");
194	    /// let r = AgentResponse::new("issue").error(e.clone());
195	    /// assert_eq!(r.render(OutputFormat::Text), e.render(OutputFormat::Text));
196	    /// assert_eq!(
197	    ///     r.render(OutputFormat::Text),
198	    ///     "error: not_found\nmessage: no issue 7\nexit_code: 1\nhelp[1]: list issues first"
199	    /// );
200	    /// assert!(r.is_error());
201	    /// ```
202	    #[must_use]
203	    pub fn error(mut self, error: DomainError) -> Self {
204	        self.error = Some(error);
205	        self
206	    }
207	
208	    /// Append a batch's per-operation outcomes as a TOON list section named `name`: one row per operation, sorted by
209	    /// index, `{index,operation,status,reason}` with `status` `completed`, `failed` or `skipped` and `reason` the
210	    /// failure reason, the skip token or `null`. The failed operations' recovery hints are appended to the response's
211	    /// recovery hints (in index order), so the document keeps one `recovery` table. A partial batch does not make the
212	    /// response an error; call [`error`](Self::error) or [`as_error`](Self::as_error) when the call failed as a whole.
213	    ///
214	    /// ```
215	    /// use michi_core::{AgentResponse, CompletedOp, FailedOp, OutputFormat, PartialSuccess, SkippedOp};
216	    ///
217	    /// let ops = PartialSuccess::try_new(
218	    ///     vec![CompletedOp::new(0, "symbols")],
219	    ///     vec![FailedOp::new(1, "refs", "not indexed")],
220	    ///     vec![SkippedOp::new(2, "search").reason("budget_exhausted")],
221	    /// )?;
222	    /// assert_eq!(
223	    ///     AgentResponse::new("batch").partial_success("ops", ops).render(OutputFormat::Text),
224	    ///     "ops[3]{index,operation,status,reason}:\n  0,symbols,completed,null\n  1,refs,failed,not indexed\n  \
225	    ///      2,search,skipped,budget_exhausted"
226	    /// );
227	    /// # Ok::<(), michi_core::DuplicateOpIndex>(())
228	    /// ```
229	    #[must_use]
230	    pub fn partial_success(mut self, name: impl Into<String>, outcome: PartialSuccess) -> Self {
231	        self.recovery.extend(outcome.recovery_hints());
232	        let fields = crate::idempotency::FIELDS.map(String::from).to_vec();
233	        self.section(Section::toon(name, fields, outcome.rows()))
234	    }
235	
236	    /// Append a status report as two sections: `tool` and `description` as a KV section named `status`, then the
237	    /// `items[N]{key,value,health,reason}:` list. Its hints are appended to the response's hints.
238	    #[must_use]
239	    pub fn status(mut self, status: StatusResponse) -> Self {
240	        let [head, items] = status.sections();
241	        self.hints.extend(status.hints);
242	        self.section(head).section(items)
243	    }
244	
245	    /// Append a pipeline's state as a TOON list section named `name`: `{id,name,status,reason}`, one row per step in
246	    /// declaration order, `status` the [`StepStatus::label`](crate::pipeline::StepStatus::label) and `reason` its
247	    /// reason or `null`. A `michi-pipeline` run record composes through its `to_pipeline()`.
248	    #[must_use]
249	    pub fn pipeline(self, name: impl Into<String>, pipeline: Pipeline) -> Self {
250	        let fields = crate::pipeline::FIELDS.map(String::from).to_vec();
251	        self.section(Section::toon(name, fields, pipeline.rows()))
252	    }
253	
254	    /// Append an already-done report as a KV section named `already_done`: `operation: …`, `status: already_done`,
255	    /// `summary: …`. Use it when an idempotency check ([`crate::resilience::already_done`]) found the operation
256	    /// completed in an earlier call.
257	    #[must_use]
258	    pub fn already_done(self, operation: impl Into<String>, summary: impl Into<String>) -> Self {
259	        self.section(crate::resilience::already_done_section(operation.into(), summary.into()))
260	    }
261	
262	    /// Append a contextual hint.
263	    #[must_use]
264	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
265	        self.hints.push(Hint::new(hint));
266	        self
267	    }
268	
269	    /// Replace all contextual hints.
270	    #[must_use]
271	    pub fn hints(mut self, hints: Vec<Hint>) -> Self {
272	        self.hints = hints;
273	        self
274	    }
275	
276	    /// Append a recovery hint.
277	    #[must_use]
278	    pub fn recovery_hint(mut self, r: RecoveryHint) -> Self {
279	        self.recovery.push(r);
280	        self
281	    }
282	
283	    /// Set the max string cell length, in chars, before truncation on the TOON path. Default:
284	    /// [`DEFAULT_TRUNCATE_CELLS`].
285	    ///
286	    /// The limit counts characters before TOON escaping and quoting, so a cell that needs quotes or escapes is
287	    /// written longer than `limit` (see [`crate::toon::ToonOptions::max_cell_len`]). The KV path is never truncated.
288	    ///
289	    /// The cap shapes the text render only. The JSON `sections` (and so `structuredContent`) carry every cell in full:
290	    /// they are the canonical data, and the text is the token-saving view of it.
291	    #[must_use]
292	    pub fn truncate_cells_at(mut self, limit: usize) -> Self {
293	        self.max_cell_len = limit;
294	        self
295	    }
296	
297	    /// Set the caller's instruction for getting a cut TOON cell in full. When a cell was cut, michi adds one line to
298	    /// `help[]` (after your own hints) that names the `truncated` block and this instruction. At most
299	    /// [`crate::toon::MAX_TRUNCATION_HINT_CHARS`] chars: a longer hint renders the `toon_validation_failed` error.
300	    /// Unset by default: michi never invents a parameter the tool may not have, and the `truncated` block still
301	    /// reports each cut. Pass tool-author text, never data.
302	    #[must_use]
303	    pub fn truncation_hint(mut self, hint: impl Into<String>) -> Self {
304	        self.truncation_hint = Some(hint.into());
305	        self
306	    }
307	
308	    /// Mark this response as an error state. To report a typed error, use [`error`](Self::error), which also renders
309	    /// its code, message and causes.
310	    #[must_use]
311	    pub fn as_error(mut self) -> Self {
312	        self.is_error = true;
313	        self
314	    }
315	
316	    /// Attach a human-facing companion block (`audience: user`).
317	    #[must_use]
318	    pub fn human_content(mut self, text: impl Into<String>) -> Self {
319	        self.human_content = Some(text.into());
320	        self
321	    }
322	
323	    /// The error's hints, the caller's hints, then michi's own truncation line when there is one: a single `help`
324	    /// block.
325	    fn hints_with<'a>(&'a self, extra: &[Hint]) -> std::borrow::Cow<'a, [Hint]> {
326	        let first = self.error.as_ref().map_or(&[][..], DomainError::hints);
327	        if extra.is_empty() && first.is_empty() {
328	            std::borrow::Cow::Borrowed(&self.hints)
329	        } else {
330	            let mut all = Vec::with_capacity(first.len() + self.hints.len() + extra.len());
331	            all.extend(first.iter().cloned());
332	            all.extend(self.hints.iter().cloned());
333	            all.extend(extra.iter().cloned());
334	            std::borrow::Cow::Owned(all)
335	        }
336	    }
337	
338	    /// The error's recovery hint, then the response's own: a single `recovery` block.
339	    fn recovery_list(&self) -> std::borrow::Cow<'_, [RecoveryHint]> {
340	        match self.error.as_ref().and_then(DomainError::get_recovery) {
341	            None => std::borrow::Cow::Borrowed(&self.recovery),
342	            Some(first) => {
343	                let mut all = Vec::with_capacity(1 + self.recovery.len());
344	                all.push(first.clone());
345	                all.extend(self.recovery.iter().cloned());
346	                std::borrow::Cow::Owned(all)
347	            }
348	        }
349	    }
350	
351	    /// The list a `Toon` section renders: borrowed from the section, with the response's cell cap and truncation hint.
352	    /// Nothing is copied, so validating and rendering cost what the output costs, not a second copy of the rows.
353	    fn list_ref<'a>(&'a self, name: &'a str, fields: &'a [String], rows: &'a [Vec<Value>]) -> ListRef<'a> {
354	        ListRef {
355	            type_name: name,
356	            fields,
357	            rows,
358	            max_cell_len: self.max_cell_len,
359	            truncation_hint: self.truncation_hint.as_deref(),
360	        }
361	    }
362	
363	    /// The blocks to render: the sections, or, for a response with nothing at all, the one empty list that names
364	    /// its type. An error, budget or provenance block stands alone, with no empty list before it.
365	    fn blocks(&self) -> std::borrow::Cow<'_, [Section]> {
366	        if self.sections.is_empty() && self.budget.is_none() && self.provenance.is_none() && self.error.is_none() {
367	            std::borrow::Cow::Owned(vec![Section::toon(self.name.as_str(), Vec::new(), Vec::new())])
368	        } else {
369	            std::borrow::Cow::Borrowed(&self.sections)
370	        }
371	    }
372	
373	    /// One section as an envelope part.
374	    fn section_part<'a>(&self, s: &'a Section) -> (Part<'a>, bool, Option<Hint>) {
375	        let total = s.shown_total();
376	        let name = s.name();
377	        match s.body() {
378	            SectionBody::Toon { fields, rows } => {
379	                match ToonDocument::validate_list(self.list_ref(name, fields, rows)) {
380	                    Ok(doc) => {
381	                        // An empty list is the definitive empty state: `name: []` and `totalCount: 0`, so a reader sees
382	                        // "zero results" and not a list that might have been dropped. A larger total the caller set
383	                        // (everything was cut) stays as it is.
384	                        let total = total.or_else(|| rows.is_empty().then_some(0));
385	                        let list = doc.render_list();
386	                        let cuts = list
387	                            .cuts
388	                            .iter()
389	                            .map(|&(row, field, removed)| crate::toon::table::Cut {
390	                                section: name,
391	                                row,
392	                                field: fields.get(field).map_or("", String::as_str),
393	                                removed,
394	                            })
395	                            .collect();
396	                        (Part { name, text: list.text, cuts, total }, false, list.extra_hint.map(Hint::new))
397	                    }
398	                    Err(e) => (Part::failed(name, "toon_validation_failed", &e.to_string()), true, None),
399	                }
400	            }
401	            SectionBody::Kv(items) => kv_part(name, items, total),
402	            // One string value under the section's name, escaped like any other value: prose cannot start a line
403	            // of its own, so it cannot forge a `help[]` line or break the document.
404	            SectionBody::Text { text, .. } => {
405	                let line = format!("{}: {}", crate::toon::escape_key(name), crate::toon::escape_value(text));
406	                (Part { name, text: line, cuts: Vec::new(), total }, false, None)
407	            }
408	        }
409	    }
410	
411	    /// Whether each block fails validation, without rendering it.
412	    fn failed_flags(&self) -> Vec<bool> {
413	        self.blocks()
414	            .iter()
415	            .map(|s| match s.body() {
416	                SectionBody::Toon { fields, rows } => {
417	                    ToonDocument::validate_list(self.list_ref(s.name(), fields, rows)).is_err()
418	                }
419	                SectionBody::Kv(items) => crate::kv::validate_keys(items).is_err(),
420	                SectionBody::Text { .. } => false,
421	            })
422	            .collect()
423	    }
424	
425	    /// The first key the body cannot render, or `None`. Sections render as root keys (a TOON list or text section
426	    /// under its name, a KV section as its item keys), beside the keys michi writes itself
427	    /// ([`crate::toon::RESERVED_ROOT_KEYS`]: the envelope blocks, the keys that follow a body, and the error
428	    /// document's keys). The reserved names are claimed whether or not michi writes that block here, so validity
429	    /// never depends on the caller's data, and a success response cannot carry `error:` or `message:` lines.
430	    /// `failed[i]` says whether block `i` failed validation: its `error` and `message` lines are michi's own, so a
431	    /// second error block (another failed block, or the response's [`DomainError`]) is a collision on `error`.
432	    /// Provenance labels sit one level down (see [`crate::provenance::label_collision`]).
433	    fn root_collision(&self, failed: &[bool]) -> Option<String> {
434	        let blocks = self.blocks();
435	        let mut seen: std::collections::HashSet<&str> = crate::toon::RESERVED_ROOT_KEYS.into_iter().collect();
436	        let mut error_block = self.error.is_some();
437	        for (s, failed) in blocks.iter().zip(failed) {
438	            if *failed {
439	                if error_block {
440	                    return Some("error".to_string());
441	                }
442	                error_block = true;
443	                continue;
444	            }
445	            let keys: Vec<&str> = match s.body() {
446	                SectionBody::Toon { .. } | SectionBody::Text { .. } => vec![s.name()],
447	                SectionBody::Kv(items) => items.iter().map(|i| i.key.as_str()).collect(),
448	            };
449	            for key in keys {
450	                if !seen.insert(key) {
451	                    return Some(key.to_string());
452	                }
453	            }
454	        }
455	        let p = self.provenance.as_ref()?;
456	        crate::provenance::label_collision(p).map(str::to_string)
457	    }
458	
459	    /// The body: the error block, sections, `budget:`, `provenance:`.
460	    ///
461	    /// Blocks are joined with one LF and empty ones are skipped. `truncated` and `totalCount` are root keys, so they
462	    /// may appear once: when one block has them they stay inline after its list; when two or more do, each becomes
463	    /// one table with a leading `section` column, after the last block.
464	    ///
465	    /// The flag is whether this response is an error: set by `as_error()` or by a block that failed validation.
466	    /// Every output surface reads its error flag from here so text, JSON and MCP never disagree.
467	    fn body(&self) -> (String, bool, Vec<Hint>) {
468	        let blocks = self.blocks();
469	        let mut parts: Vec<Part<'_>> = Vec::with_capacity(blocks.len());
470	        let mut failed = false;
471	        let mut flags: Vec<bool> = Vec::with_capacity(blocks.len());
472	        let mut extras: Vec<Hint> = Vec::new();
473	        for s in blocks.iter() {
474	            let (part, part_failed, extra) = self.section_part(s);
475	            failed |= part_failed;
476	            flags.push(part_failed);
477	            // One line per cut response is enough: every section's line says the same thing.
478	            if let Some(h) = extra {
479	                if !extras.contains(&h) {
480	                    extras.push(h);
481	                }
482	            }
483	            parts.push(part);
484	        }
485	        // Two blocks writing one root key would be invalid TOON. Like any other bad input the whole body becomes the
486	        // visible validation error, so the caller sees it instead of a document a decoder rejects.
487	        if let Some(key) = self.root_collision(&flags) {
488	            return (collision_body(&key), true, Vec::new());
489	        }
490	        let cutters = parts.iter().filter(|p| !p.cuts.is_empty()).count();
491	        let totals = parts.iter().filter(|p| p.total.is_some()).count();
492	        let mut out = String::with_capacity(parts.iter().map(|p| p.text.len() + 24).sum::<usize>() + 256);
493	        if let Some(e) = &self.error {
494	            crate::error::push_error_fields(&mut out, e);
495	        }
496	        for p in &parts {
497	            join_block(&mut out, &p.text);
498	            if cutters == 1 {
499	                crate::toon::table::push_truncated(&mut out, &p.cuts, false);
500	            }
501	            if let (1, Some(n)) = (totals, p.total) {
502	                join_block(&mut out, &format!("totalCount: {n}"));
503	            }
504	        }
505	        if cutters >= 2 {
506	            let cuts: Vec<crate::toon::table::Cut<'_>> = parts.iter().flat_map(|p| p.cuts.iter().cloned()).collect();
507	            crate::toon::table::push_truncated(&mut out, &cuts, true);
508	        }
509	        if totals >= 2 {
510	            use crate::toon::table::{self, Cell};
511	            table::push_header(&mut out, "totalCount", totals, ["section", "total"]);
512	            for p in &parts {
513	                if let Some(total) = p.total {
514	                    table::push_row(&mut out, &[Cell::Str(p.name), Cell::count(total)]);
515	                }
516	            }
517	        }
518	        if let Some(b) = &self.budget {
519	            join_block(&mut out, &crate::budget::render_budget_block(b, &self.sections));
520	        }
521	        if let Some(p) = &self.provenance {
522	            join_block(&mut out, &crate::provenance::render_provenance_block(p));
523	        }
524	        (out, failed || self.is_error || self.error.is_some(), extras)
525	    }
526	
527	    /// Compose the text document: body, help block, recovery block. Each part is a TOON 4.4 document without a
528	    /// trailing newline and the append helpers join them with one LF, so the result is one root object whose keys
529	    /// are unique (the body cannot use `totalCount`, `help`, `recovery` or `truncated`). Appends to `body` in place.
530	    fn finish_text(&self, mut body: String, extra: &[Hint]) -> String {
531	        let hints = self.hints_with(extra);
532	        let recovery = self.recovery_list();
533	        if !hints.is_empty() || !recovery.is_empty() {
534	            body.reserve(1 + hints.len() * 60 + recovery.len() * 80);
535	        }
536	        crate::hints::append_hints(&mut body, &hints);
537	        crate::recovery::append_recovery(&mut body, &recovery);
538	        body
539	    }
