588	    /// Build the MCP `CallToolResult` for this response.
589	    #[must_use]
590	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
591	        let (body, is_error, extra) = self.body();
592	        let structured_content = self.json_from_body(&body, is_error, &extra);
593	        let mut content = vec![crate::mcp::ContentBlock {
594	            text: self.finish_text(body, &extra),
595	            audience: vec![crate::audience::Audience::Assistant],
596	        }];
597	        if let Some(human) = &self.human_content {
598	            content.push(crate::mcp::ContentBlock {
599	                text: human.clone(),
600	                audience: vec![crate::audience::Audience::User],
601	            });
602	        }
603	        crate::mcp::CallToolResult::new(
604	            content,
605	            is_error,
606	            Some(crate::mcp::JsonObject::from_trusted(structured_content)),
607	        )
608	    }
