610	    fn render_json(&self) -> String {
611	        let (body, is_error, extra) = self.body();
612	        self.json_from_body(&body, is_error, &extra)
613	    }
614	
615	    fn json_from_body(&self, body: &str, is_error: bool, extra: &[Hint]) -> String {
616	        let hints = self.hints_with(extra);
617	        let recovery = self.recovery_list();
618	        let capacity =
619	            body.len() + hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>() + recovery.len() * 64 + 64;
620	        let mut out = String::with_capacity(capacity + 128);
621	        out.push_str("{\"body\":");
622	        json::push_str(&mut out, body);
623	        if let Some(e) = &self.error {
624	            out.push_str(",\"error\":");
625	            crate::error::push_error_json(&mut out, e);
626	        }
627	        if !self.sections.is_empty() {
628	            out.push_str(",\"sections\":");
629	            json::push_array(&mut out, &self.sections, push_section_json);
630	        }
631	        if let Some(b) = &self.budget {
632	            out.push_str(",\"budget\":");
633	            crate::budget::push_budget_json(&mut out, b, &self.sections);
634	        }
635	        if let Some(p) = &self.provenance {
636	            out.push_str(",\"provenance\":");
637	            crate::provenance::push_provenance_json(&mut out, p);
638	        }
639	        out.push_str(",\"hints\":");
640	        json::push_str_array(&mut out, hints.iter().map(Hint::as_str));
641	        out.push_str(",\"recovery\":");
642	        json::push_array(&mut out, recovery.iter(), json::push_recovery);
643	        out.push_str(",\"isError\":");
644	        json::push_bool(&mut out, is_error);
645	        out.push('}');
646	        out
647	    }
648	}
