650	/// The body that replaces rows or items that cannot form a valid document: `error: <code>` and the quoted message.
651	fn validation_error_body(code: &str, message: &str) -> String {
652	    let message = crate::toon::escape_value(message);
653	    let mut out = String::with_capacity(17 + code.len() + message.len());
654	    out.push_str("error: ");
655	    out.push_str(code);
656	    out.push_str("\nmessage: ");
657	    out.push_str(&message);
658	    out
659	}
660	
661	/// The body for two blocks that would write the same root key.
662	fn collision_body(key: &str) -> String {
663	    validation_error_body(
664	        "toon_validation_failed",
665	        &format!("duplicate root key '{key}': give every section and KV key a distinct name"),
666	    )
667	}
668	
669	/// One block of an envelope body before the root-level `truncated` and `totalCount` keys are placed.
670	struct Part<'a> {
671	    /// The block's name, the `section` column when several blocks share a root key.
672	    name: &'a str,
673	    /// The block's text without its `truncated` block or `totalCount` line.
674	    text: String,
675	    /// Cut cells, for the `truncated` block.
676	    cuts: Vec<crate::toon::table::Cut<'a>>,
677	    /// The `totalCount` this block reports, when it reports one.
678	    total: Option<usize>,
679	}
680	
681	impl<'a> Part<'a> {
682	    /// A block that failed validation: the error body replaces its content and it reports no count.
683	    fn failed(name: &'a str, code: &str, message: &str) -> Self {
684	        Self { name, text: validation_error_body(code, message), cuts: Vec::new(), total: None }
685	    }
686	}
687	
688	/// A KV block as a part. No items still reports a larger total the caller set.
689	fn kv_part<'a>(name: &'a str, items: &[KvItem], total: Option<usize>) -> (Part<'a>, bool, Option<Hint>) {
690	    if items.is_empty() {
691	        return (Part { name, text: String::new(), cuts: Vec::new(), total }, false, None);
692	    }
693	    match crate::kv::render_kv(items) {
694	        Ok(text) => (Part { name, text, cuts: Vec::new(), total }, false, None),
695	        Err(e) => (Part::failed(name, "kv_validation_failed", &e.to_string()), true, None),
696	    }
697	}
698	
699	/// Append `block` after a LF unless either side is empty.
700	fn join_block(out: &mut String, block: &str) {
701	    if block.is_empty() {
702	        return;
703	    }
704	    if !out.is_empty() {
705	        out.push('\n');
706	    }
707	    out.push_str(block);
708	}
709	
710	/// One section as the JSON object spec 07 section 5 describes. Rows carry the full values: the per-cell cap shapes
711	/// the text render, and `structuredContent` is the typed copy of the same data. `returnedCount` and `truncated` are
712	/// the section's own derived facts, the ones the text render uses.
713	fn push_section_json(out: &mut String, s: &Section) {
714	    out.push_str("{\"name\":");
715	    json::push_str(out, s.name());
716	    match s.body() {
717	        SectionBody::Toon { fields, rows } => {
718	            out.push_str(",\"kind\":\"toon\",\"fields\":");
719	            json::push_str_array(out, fields.iter().map(String::as_str));
720	            out.push_str(",\"rows\":");
721	            json::push_array(out, rows, |out, row| json::push_array(out, row, json::push_value));
722	        }
723	        SectionBody::Kv(items) => {
724	            out.push_str(",\"kind\":\"kv\",\"items\":");
725	            json::push_array(out, items, |out, item| {
726	                out.push_str("{\"key\":");
727	                json::push_str(out, &item.key);
728	                out.push_str(",\"value\":");
729	                json::push_kv_value(out, &item.value);
730	                out.push('}');
731	            });
732	        }
733	        SectionBody::Text { text, .. } => {
734	            out.push_str(",\"kind\":\"text\",\"text\":");
735	            json::push_str(out, text);
736	        }
737	    }
738	    out.push_str(",\"returnedCount\":");
739	    json::push_uint(out, s.count() as u64);
740	    if let Some(total) = s.total() {
741	        out.push_str(",\"totalCount\":");
742	        json::push_uint(out, total as u64);
743	    }
744	    out.push_str(",\"truncated\":");
745	    json::push_bool(out, s.truncated());
746	    out.push('}');
747	}
