1	//! Repeatable response sections: several named blocks in one [`crate::AgentResponse`].
2	
3	use crate::kv::KvItem;
4	use crate::toon::Value;
5	
6	/// One named block within a response. A response may hold any number; they render in insertion order.
7	///
8	/// A section is a root key of the rendered TOON document: a list or text section under its `name`, a KV section as its
9	/// item keys. Root keys must be unique, so two sections cannot share a name, and no name or KV key may be one of the
10	/// keys michi writes itself (`budget`, `sections`, `provenance`, `truncated`, `totalCount`, `help`, `recovery`,
11	/// `error`, `message`, `causes`, `exit_code`). A response that breaks this renders the `toon_validation_failed` (or
12	/// `kv_validation_failed`) error naming the key, never invalid TOON.
13	///
14	/// The fields are private, so what a section reports about itself has one source each: [`count`](Self::count) is the
15	/// body's rows or items, [`total`](Self::total) is the one number the caller sets, and
16	/// [`truncated`](Self::truncated) is derived from those two. No section can print `totalCount: 5` while its JSON says
17	/// it was not cut.
18	///
19	/// # Stability
20	///
21	/// The multi-section envelope (this type, [`crate::BudgetSummary`], [`crate::ProvenanceBlock`]) is unstable. It
22	/// shipped ahead of a second independent consumer (ADR 10), so its shape may change before 1.0, and 1.0 promises only
23	/// what consumers have used by then.
24	#[derive(Debug, Clone)]
25	pub struct Section {
26	    name: String,
27	    body: SectionBody,
28	    total_count: Option<usize>,
29	}
30	
31	/// What a [`Section`] holds.
32	#[derive(Debug, Clone)]
33	#[non_exhaustive]
34	pub enum SectionBody {
35	    /// A uniform list, rendered as a TOON list with the response's per-cell truncation applied.
36	    Toon {
37	        /// Ordered, distinct field names.
38	        fields: Vec<String>,
39	        /// Rows, parallel to `fields`.
40	        rows: Vec<Vec<Value>>,
41	    },
42	    /// A single receipt or a small set of labelled scalars.
43	    Kv(Vec<KvItem>),
44	    /// One string value, rendered as `name: <value>` and escaped like any other TOON string (quoted when it has a
45	    /// newline, a colon, or looks like a number). Prose cannot start a line of its own, so it cannot forge a `help[]`
46	    /// line. It is not a way to insert a fragment of TOON.
47	    Text {
48	        /// The value.
49	        text: String,
50	        /// How many items the prose stands for, since michi cannot count items in prose.
51	        count: usize,
52	    },
53	}
54	
55	impl Section {
56	    /// A TOON list section. Its count is `rows.len()`.
57	    #[must_use]
58	    pub fn toon(name: impl Into<String>, fields: Vec<String>, rows: Vec<Vec<Value>>) -> Self {
59	        Self::with(name, SectionBody::Toon { fields, rows })
60	    }
61	
62	    /// A key-value section. Its count is `items.len()`.
63	    #[must_use]
64	    pub fn kv(name: impl Into<String>, items: Vec<KvItem>) -> Self {
65	        Self::with(name, SectionBody::Kv(items))
66	    }
67	
68	    /// A text section: a single string value, rendered as `name: <escaped body>`. Its count is 1 for non-empty text
69	    /// and 0 for empty; use [`text_with_count`](Self::text_with_count) when the prose stands for more items.
70	    #[must_use]
71	    pub fn text(name: impl Into<String>, body: impl Into<String>) -> Self {
72	        let text = body.into();
73	        let count = usize::from(!text.is_empty());
74	        Self::with(name, SectionBody::Text { text, count })
75	    }
76	
77	    /// A text section that stands for `count` items, such as a summary of `count` matches.
78	    #[must_use]
79	    pub fn text_with_count(name: impl Into<String>, body: impl Into<String>, count: usize) -> Self {
80	        Self::with(name, SectionBody::Text { text: body.into(), count })
81	    }
82	
83	    fn with(name: impl Into<String>, body: SectionBody) -> Self {
84	        Self { name: name.into(), body, total_count: None }
85	    }
86	
87	    /// Record how many items existed before a cut. `Some(n)` with `n` greater than [`count`](Self::count) renders
88	    /// `totalCount: n` and makes [`truncated`](Self::truncated) true.
89	    #[must_use]
90	    pub fn total_count(mut self, total: Option<usize>) -> Self {
91	        self.total_count = total;
92	        self
93	    }
94	
95	    /// The section's type name: the identifier at the head of its TOON line, and the key of a text body. A KV body
96	    /// prints no heading, so there the name only labels it for the caller (and for `sections` in JSON).
97	    #[must_use]
98	    pub fn name(&self) -> &str {
99	        &self.name
100	    }
101	
102	    /// The section's contents.
103	    #[must_use]
104	    pub fn body(&self) -> &SectionBody {
105	        &self.body
106	    }
107	
108	    /// How many items this section carries: `rows.len()` or `items.len()` for `Toon` and `Kv` bodies, the count given
109	    /// to the constructor for `Text`.
110	    #[must_use]
111	    pub fn count(&self) -> usize {
112	        match &self.body {
113	            SectionBody::Toon { rows, .. } => rows.len(),
114	            SectionBody::Kv(items) => items.len(),
115	            SectionBody::Text { count, .. } => *count,
116	        }
117	    }
118	
119	    /// The pre-cut total set with [`total_count`](Self::total_count), as given.
120	    #[must_use]
121	    pub fn total(&self) -> Option<usize> {
122	        self.total_count
123	    }
124	
125	    /// Whether this section was cut: its total exceeds its count. Derived, never set.
126	    #[must_use]
127	    pub fn truncated(&self) -> bool {
128	        self.shown_total().is_some()
129	    }
130	
131	    /// The `totalCount` to render: the total only when it exceeds [`count`](Self::count).
132	    pub(crate) fn shown_total(&self) -> Option<usize> {
133	        self.total_count.filter(|n| *n > self.count())
134	    }
135	}
136	
137	#[cfg(test)]
138	mod tests {
139	    use super::*;
140	
141	    #[test]
142	    fn truncated_is_exactly_total_above_count() {
143	        let one = || Section::toon("t", vec!["a".into()], vec![vec![Value::Int(1)]]);
144	        assert!(one().total_count(Some(2)).truncated());
145	        assert!(!one().total_count(Some(1)).truncated());
146	        assert!(!one().total_count(Some(0)).truncated());
147	        assert!(!one().truncated());
148	        assert!(Section::text_with_count("n", "x", 3).total_count(Some(4)).truncated());
149	        assert!(!Section::text_with_count("n", "x", 3).total_count(Some(3)).truncated());
150	    }
151	}
152

