222	    fn peek(&self) -> Option<u8> {
223	        self.bytes.get(self.pos).copied()
224	    }
225	
226	    fn fail(&self, what: &str) -> StructuredContentError {
227	        StructuredContentError::InvalidJson { reason: format!("{what} at byte {}", self.pos) }
228	    }
229	
230	    fn skip_ws(&mut self) {
231	        while matches!(self.peek(), Some(b' ' | b'\t' | b'\n' | b'\r')) {
232	            self.pos += 1;
233	        }
234	    }
235	
236	    fn eat(&mut self, b: u8) -> bool {
237	        let hit = self.peek() == Some(b);
238	        if hit {
239	            self.pos += 1;
240	        }
241	        hit
242	    }
243	
244	    fn literal(&mut self, word: &[u8]) -> Result<(), StructuredContentError> {
245	        if self.bytes[self.pos..].starts_with(word) {
246	            self.pos += word.len();
247	            Ok(())
248	        } else {
249	            Err(self.fail("expected a JSON value"))
250	        }
251	    }
252	
253	    fn value(&mut self, depth: usize) -> Result<(), StructuredContentError> {
254	        match self.peek() {
255	            Some(b'{') => self.container(depth, b'}', true),
256	            Some(b'[') => self.container(depth, b']', false),
257	            Some(b'"') => self.string(),
258	            Some(b't') => self.literal(b"true"),
259	            Some(b'f') => self.literal(b"false"),
260	            Some(b'n') => self.literal(b"null"),
261	            Some(b'-' | b'0'..=b'9') => self.number(),
262	            _ => Err(self.fail("expected a JSON value")),
263	        }
264	    }
265	
266	    /// An object (`keyed`) or array, whose opening bracket is at `pos`.
267	    fn container(&mut self, depth: usize, close: u8, keyed: bool) -> Result<(), StructuredContentError> {
268	        if depth >= MAX_JSON_DEPTH {
269	            return Err(self.fail("nesting too deep"));
270	        }
271	        self.pos += 1;
272	        self.skip_ws();
273	        if self.eat(close) {
274	            return Ok(());
275	        }
276	        loop {
277	            if keyed {
278	                if self.peek() != Some(b'"') {
279	                    return Err(self.fail("expected a string key"));
280	                }
281	                self.string()?;
282	                self.skip_ws();
283	                if !self.eat(b':') {
284	                    return Err(self.fail("expected `:`"));
285	                }
286	                self.skip_ws();
287	            }
288	            self.value(depth + 1)?;
289	            self.skip_ws();
290	            if self.eat(close) {
291	                return Ok(());
292	            }
293	            if !self.eat(b',') {
294	                return Err(self.fail("expected `,` or a closing bracket"));
295	            }
296	            self.skip_ws();
297	        }
