1	//! Every outcome michi renders composes into one `AgentResponse` (docs/spec/06-decisions.md, "Outcomes compose into
2	//! one response"): `DomainError`, `PartialSuccess`, `StatusResponse`, `Pipeline` and `already_done` become sections or
3	//! the error block of the response, and render through its one writer on every surface. Each probe below was
4	//! impossible before: the type had its own document, and two documents could not be joined into one valid one.
5	
6	use michi_core::kv::{KvItem, KvValue};
7	use michi_core::pipeline::{Pipeline, PipelineStep, SkipReason, StepStatus};
8	use michi_core::toon::Value;
9	use michi_core::{
10	    AgentResponse, Audience, BudgetSummary, CompletedOp, DomainError, ErrorCode, FailedOp, Health, OutputFormat,
11	    PartialSuccess, ProvenanceBlock, RecoveryHint, Section, SkippedOp, StatusItem, StatusResponse,
12	};
13	use proptest::prelude::*;
14	
15	mod support;
16	use support::toon_parser::{decode, Doc, Node, Prim};
17	
18	fn valid(text: &str) -> Doc {
19	    decode(text).unwrap_or_else(|e| panic!("not conformant TOON: {e}\n{text}"))
20	}
21	
22	fn json(r: &AgentResponse) -> serde_json::Value {
23	    let text = r.render(OutputFormat::Json);
24	    serde_json::from_str(&text).unwrap_or_else(|e| panic!("invalid JSON: {e}\n{text}"))
25	}
26	
27	fn keys(v: &serde_json::Value) -> Vec<&str> {
28	    v.as_object().map(|o| o.keys().map(String::as_str).collect()).unwrap_or_default()
29	}
30	
31	fn fields(names: &[&str]) -> Vec<String> {
32	    names.iter().map(|s| (*s).to_string()).collect()
33	}
34	
35	/// The spec 07 section 4 batch: four ops, two answered, one failed with a recovery, one skipped.
36	fn batch_ops() -> PartialSuccess {
37	    PartialSuccess::try_new(
38	        vec![CompletedOp::new(1, "dependents"), CompletedOp::new(0, "symbols")],
39	        vec![FailedOp::new(2, "refs", "symbol not found: RetryPolicy")
40	            .recovery(RecoveryHint::new("search").param("query", KvValue::Text("RetryPolicy".into())))],
41	        vec![SkippedOp::new(3, "search").reason("budget_exhausted")],
42	    )
43	    .expect("one outcome per index")
44	}
45	
46	fn batch() -> AgentResponse {
47	    AgentResponse::new("batch")
48	        .section(Section::toon("symbols", fields(&["name", "kind"]), vec![vec!["RetryPolicy".into(), "struct".into()]]))
49	        .section(Section::toon("dependents", fields(&["name"]), vec![vec!["Client".into()]]).total_count(Some(3)))
50	        .partial_success("ops", batch_ops())
51	        .budget(BudgetSummary::new().tokens_used(812).max_tokens(1000))
52	        .provenance(ProvenanceBlock::new().entry("analyzer", "rust-analyzer").fingerprint("abc123"))
53	        .hint("narrow the search query")
54	}
55	
56	#[test]
57	fn the_spec_07_batch_is_one_valid_toon_document() {
58	    let text = batch().render(OutputFormat::Text);
59	    assert_eq!(
60	        text,
61	        "symbols[1]{name,kind}:\n  RetryPolicy,struct\n\
62	         dependents[1]{name}:\n  Client\ntotalCount: 3\n\
63	         ops[4]{index,operation,status,reason}:\n  0,symbols,completed,null\n  1,dependents,completed,null\n  \
64	         2,refs,failed,\"symbol not found: RetryPolicy\"\n  3,search,skipped,budget_exhausted\n\
65	         budget:\n  tokensUsed: 812\n  maxTokens: 1000\n  truncated: true\n\
66	         sections[3]{name,returned,total,truncated}:\n  symbols,1,null,false\n  dependents,1,3,true\n  \
67	         ops,4,null,false\n\
68	         provenance:\n  analyzer: rust-analyzer\n  fingerprint: abc123\n\
69	         help[1]: narrow the search query\n\
70	         recovery[1]{tool,params,reason}:\n  search,\"{\\\"query\\\":\\\"RetryPolicy\\\"}\",null"
71	    );
72	    let doc = valid(&text);
73	    // `recovery` appears once, at the root, carrying the failed op's hint: it is not a key of the ops block.
74	    assert_eq!(doc.entries.iter().filter(|(k, _)| k == "recovery").count(), 1);
75	    let Some(Node::Table { rows, .. }) = doc.get("ops") else { panic!("ops is a table: {doc:?}") };
76	    let indices: Vec<&Prim> = rows.iter().map(|r| &r[0]).collect();
77	    assert_eq!(
78	        indices,
79	        [&Prim::Num("0".into()), &Prim::Num("1".into()), &Prim::Num("2".into()), &Prim::Num("3".into())]
80	    );
81	}
