83	#[test]
84	fn the_spec_07_batch_is_one_json_object_with_the_ops_as_a_section() {
85	    let r = batch();
86	    let v = json(&r);
87	    assert_eq!(keys(&v), ["body", "sections", "budget", "provenance", "hints", "recovery", "isError"]);
88	    assert_eq!(v["isError"], false, "a partial batch is not a failed tool call");
89	    let ops = &v["sections"][2];
90	    assert_eq!(ops["name"], "ops");
91	    assert_eq!(ops["kind"], "toon");
92	    assert_eq!(ops["fields"], serde_json::json!(["index", "operation", "status", "reason"]));
93	    assert_eq!(ops["rows"][2], serde_json::json!([2, "refs", "failed", "symbol not found: RetryPolicy"]));
94	    assert_eq!(ops["rows"][0], serde_json::json!([0, "symbols", "completed", null]));
95	    assert_eq!(v["recovery"], serde_json::json!([{"tool": "search", "params": {"query": "RetryPolicy"}}]));
96	    let result = r.to_call_tool_result();
97	    assert_eq!(result.content[0].text, r.render(OutputFormat::Text));
98	    let structured: serde_json::Value =
99	        serde_json::from_str(result.structured_content.as_ref().map(michi_core::JsonObject::as_str).unwrap_or(""))
100	            .expect("JSON");
101	    assert_eq!(structured, v);
102	    assert_eq!(r.render_for(Audience::Assistant), r.render(OutputFormat::Text));
103	}
