105	// ---- DomainError: one error shape ----
106	
107	fn timeout() -> DomainError {
108	    DomainError::new(ErrorCode::Timeout, "POST /charge timed out")
109	        .cause("upstream closed the connection")
110	        .recovery(RecoveryHint::new("get_charge").param("id", KvValue::Text("ch_1".into())))
111	}
112	
113	#[test]
114	fn a_domain_error_composes_with_sections_into_one_document() {
115	    let r = AgentResponse::new("charge")
116	        .kv_items(vec![KvItem::new("attempted", KvValue::Int(1))])
117	        .error(timeout())
118	        .hint("check the dashboard");
119	    assert!(r.is_error());
120	    let text = r.render(OutputFormat::Text);
121	    assert_eq!(
122	        text,
123	        "error: timeout\nmessage: POST /charge timed out\ncauses[1]: upstream closed the connection\nexit_code: 1\n\
124	         attempted: 1\n\
125	         help[2]: \"the operation may have taken effect; verify whether it completed before retrying, unless it is \
126	         idempotent\",check the dashboard\n\
127	         recovery[1]{tool,params,reason}:\n  get_charge,\"{\\\"id\\\":\\\"ch_1\\\"}\",null"
128	    );
129	    valid(&text);
130	    let v = json(&r);
131	    assert_eq!(keys(&v), ["body", "error", "sections", "hints", "recovery", "isError"]);
132	    assert_eq!(
133	        v["error"],
134	        serde_json::json!({
135	            "code": "timeout",
136	            "message": "POST /charge timed out",
137	            "causes": ["upstream closed the connection"],
138	            "retryable": false
139	        })
140	    );
141	    assert_eq!(v["isError"], true);
142	    assert!(r.to_call_tool_result().is_error);
143	}
