145	#[test]
146	fn a_domain_error_renders_the_same_alone_and_in_a_response() {
147	    for e in [timeout(), DomainError::new(ErrorCode::NotFound, "no such issue").hint("list issues first")] {
148	        let alone = AgentResponse::new("anything").error(e.clone());
149	        for format in [OutputFormat::Text, OutputFormat::Json] {
150	            assert_eq!(e.render(format), alone.render(format), "{format:?}");
151	        }
152	        assert_eq!(e.to_call_tool_result(), alone.to_call_tool_result());
153	    }
154	}
