156	#[test]
157	fn there_is_one_error_json_shape() {
158	    // A DomainError and an error response carry the same keys, and `recovery` is an array in both.
159	    let from_error: serde_json::Value =
160	        serde_json::from_str(&timeout().render(OutputFormat::Json)).expect("DomainError JSON");
161	    let marked: serde_json::Value = serde_json::from_str(
162	        &AgentResponse::new("t").as_error().recovery_hint(RecoveryHint::new("x")).render(OutputFormat::Json),
163	    )
164	    .expect("response JSON");
165	    assert_eq!(keys(&from_error), ["body", "error", "hints", "recovery", "isError"]);
166	    assert_eq!(keys(&marked), ["body", "hints", "recovery", "isError"]);
167	    assert!(from_error["recovery"].is_array() && marked["recovery"].is_array());
168	    assert_eq!(keys(&from_error["error"]), ["code", "message", "causes", "retryable"]);
169	    // `body` is the document before `help` and `recovery`, as in every response's JSON.
170	    let text = timeout().render(OutputFormat::Text);
171	    let body = from_error["body"].as_str().expect("body is a string");
172	    assert!(text.starts_with(body) && body.ends_with("exit_code: 1"), "{body}");
173	}
