195	#[test]
196	fn partial_success_composes_without_a_root_recovery_of_its_own() {
197	    // Before: `PartialSuccess::render` wrote its own `recovery[N]` table, a root key `AgentResponse` writes too, so
198	    // the two could not be one document.
199	    let r = AgentResponse::new("t").partial_success("ops", batch_ops()).recovery_hint(RecoveryHint::new("retry_all"));
200	    let text = r.render(OutputFormat::Text);
