344	        Just('\u{1}'),
345	        Just('\u{2028}'),
346	        proptest::char::range('a', 'z'),
347	        proptest::char::range('0', '9'),
348	    ];
349	    proptest::collection::vec(c, 0..16).prop_map(|c| c.into_iter().collect::<String>())
350	}
351	
352	fn arb_error() -> impl Strategy<Value = DomainError> {
353	    (0usize..ErrorCode::ALL.len(), hostile(), proptest::collection::vec(hostile(), 0..3), any::<bool>(), any::<bool>())
354	        .prop_map(|(code, message, causes, retryable, recovery)| {
355	            let mut e = DomainError::new(ErrorCode::ALL[code], message).retryable(retryable);
356	            for c in causes {
357	                e = e.cause(c);
358	            }
359	            if recovery {
360	                e = e.recovery(RecoveryHint::new("retry"));
361	            }
362	            e
363	        })
364	}
365	
366	fn arb_partial() -> impl Strategy<Value = PartialSuccess> {
367	    proptest::collection::vec((0u8..3, hostile(), proptest::option::of(hostile()), any::<bool>()), 0..6).prop_map(
368	        |ops| {
369	            let (mut completed, mut failed, mut skipped) = (Vec::new(), Vec::new(), Vec::new());
370	            // Indices are scattered so the composed table sorts them.
371	            for (i, (kind, name, reason, recovery)) in ops.into_iter().enumerate().rev() {
372	                let index = i * 7;
373	                match kind {
374	                    0 => completed.push(CompletedOp::new(index, name)),
375	                    1 => {
376	                        let f = FailedOp::new(index, name, reason.unwrap_or_default());
377	                        failed.push(if recovery { f.recovery(RecoveryHint::new("fix")) } else { f });
378	                    }
379	                    _ => {
380	                        let s = SkippedOp::new(index, name);
381	                        skipped.push(match reason {
382	                            Some(r) => s.reason(r),
383	                            None => s,
384	                        });
385	                    }
386	                }
387	            }
388	            PartialSuccess::try_new(completed, failed, skipped).expect("distinct indices")
389	        },
390	    )
391	}
392	
393	fn arb_status() -> impl Strategy<Value = StatusResponse> {
394	    (hostile(), hostile(), proptest::collection::vec((hostile(), hostile(), 0u8..4), 0..4), hostile()).prop_map(
395	        |(tool, desc, items, hint)| {
396	            let items = items
397	                .into_iter()
398	                .map(|(k, v, h)| {
399	                    let item = StatusItem::new(k, KvValue::Text(v.clone()));
400	                    match h {
401	                        0 => item,
402	                        1 => item.health(Health::Ok),
403	                        2 => item.health(Health::Degraded(v)),
404	                        _ => item.health(Health::Error(v)),
405	                    }
406	                })
407	                .collect();
408	            StatusResponse::new(tool, desc, items).hints(vec![hint.into()])
409	        },
410	    )
411	}
412	
413	fn arb_pipeline() -> impl Strategy<Value = Pipeline> {
414	    proptest::collection::vec((hostile(), hostile(), 0usize..StepStatus::ALL.len()), 0..5).prop_map(|steps| {
415	        Pipeline::new(steps.into_iter().map(|(id, name, s)| PipelineStep::new(id, name, StepStatus::ALL[s])).collect())
416	    })
417	}
418	
419	proptest! {
420	    #![proptest_config(ProptestConfig::with_cases(256))]
421	
422	    #[test]
423	    fn every_mix_of_outcomes_is_one_valid_toon_document_and_one_json_object(
424	        error in proptest::option::of(arb_error()),
425	        partial in proptest::option::of(arb_partial()),
426	        status in proptest::option::of(arb_status()),
427	        pipeline in proptest::option::of(arb_pipeline()),
428	        done in proptest::option::of((hostile(), hostile())),
429	        rows in proptest::collection::vec(hostile(), 0..4),
430	        hint in hostile(),
431	        cap in 1usize..40,
432	    ) {
433	        let mut r = AgentResponse::new("batch").truncate_cells_at(cap);
434	        let rows = rows.iter().map(|c| vec![Value::from(c.clone())]).collect();
435	        r = r.section(Section::toon("results", fields(&["v"]), rows));
436	        let has_error = error.is_some();
437	        if let Some(e) = error {
438	            r = r.error(e);
439	        }
440	        if let Some(ps) = partial {
441	            r = r.partial_success("ops", ps);
442	        }
443	        if let Some(s) = status {
444	            r = r.status(s);
445	        }
446	        if let Some(p) = pipeline {
447	            r = r.pipeline("step", p);
448	        }
449	        if let Some((op, summary)) = done {
450	            r = r.already_done(op, summary);
451	        }
452	        let r = r.hint(hint).budget(BudgetSummary::new().tokens_used(1));
453	
454	        let text = r.render(OutputFormat::Text);
455	        let doc = decode(&text);
456	        prop_assert!(doc.is_ok(), "invalid TOON: {:?}\n{}", doc.err(), text);
457	        let v: serde_json::Value = match serde_json::from_str(&r.render(OutputFormat::Json)) {
458	            Ok(v) => v,
459	            Err(e) => return Err(TestCaseError::fail(format!("invalid JSON: {e}"))),
460	        };
461	        prop_assert_eq!(v["isError"].as_bool(), Some(r.is_error()));
462	        prop_assert_eq!(r.is_error(), r.to_call_tool_result().is_error);
463	        prop_assert_eq!(v.get("error").is_some(), has_error);
464	        if has_error {
465	            prop_assert!(r.is_error());
466	            prop_assert!(text.starts_with("error: "), "{}", text);
467	        }
468	        prop_assert_eq!(v["body"].as_str().map(|b| text.starts_with(b)), Some(true));
469	        // One `help`, one `recovery`, one `error`: TOON forbids a repeated root key, and the decoder checks it.
470	        let doc = doc.unwrap_or_else(|_| unreachable!());
471	        for key in ["help", "recovery", "error"] {
472	            prop_assert!(doc.entries.iter().filter(|(k, _)| k == key).count() <= 1, "{} twice in\n{}", key, text);
473	        }
474	    }
475	}
