1	//! Response-level budget report: what ceilings a caller worked under and what the response cost. michi renders a
2	//! budget; it never computes one. See `docs/spec/07-wisp-and-monokl-envelope.md` §2.
3	
4	use std::fmt::Write as _;
5	
6	use crate::section::Section;
7	use crate::toon::table::{self, Cell};
8	
9	/// What a budget block renders: the ceilings a caller was working under and what the response cost against them.
10	///
11	/// Every number is optional, so a caller who measured only tokens sets two fields and leaves the rest empty. Absent
12	/// fields are omitted from the rendered block, never written as `null`. `u64` rather than `usize` because these
13	/// values reach JSON, where a platform-dependent width means nothing.
14	///
15	/// The per-section roll-up is not part of this type: michi derives it from the response's own sections when it
16	/// renders, so the roll-up can only name sections the response holds, with the counts they render.
17	///
18	/// `#[non_exhaustive]`: start from [`BudgetSummary::new`] or `Default` and use the builder methods.
19	///
20	/// # Stability
21	///
22	/// Part of the multi-section envelope, which is unstable until a second independent consumer has used it (ADR 10).
23	/// Its shape may change before 1.0.
24	#[derive(Debug, Clone, Default, PartialEq, Eq)]
25	#[cfg_attr(feature = "serde", derive(serde::Serialize))]
26	#[cfg_attr(feature = "serde", serde(rename_all = "camelCase"))]
27	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
28	#[cfg_attr(feature = "schemars", schemars(rename_all = "camelCase"))]
29	#[non_exhaustive]
30	pub struct BudgetSummary {
31	    /// Token ceiling the caller set.
32	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
33	    pub max_tokens: Option<u64>,
34	    /// Byte ceiling the caller set.
35	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
36	    pub max_bytes: Option<u64>,
37	    /// Item ceiling the caller set.
38	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
39	    pub max_items: Option<u64>,
40	    /// Tokens the response cost, as the caller measured it.
41	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
42	    pub tokens_used: Option<u64>,
43	    /// Bytes the response cost, as the caller measured it.
44	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
45	    pub bytes_used: Option<u64>,
46	    /// Whether the budget dropped something the sections cannot show, such as a whole section left out. The rendered
47	    /// `truncated` is also true whenever a section of the response was cut.
48	    pub truncated: bool,
49	}
50	
51	impl BudgetSummary {
52	    /// An empty summary: no ceilings, no measurements, not truncated.
53	    #[must_use]
54	    pub fn new() -> Self {
55	        Self::default()
56	    }
57	
58	    /// Set the token ceiling.
59	    #[must_use]
60	    pub fn max_tokens(mut self, n: u64) -> Self {
61	        self.max_tokens = Some(n);
62	        self
63	    }
64	
65	    /// Set the byte ceiling.
66	    #[must_use]
67	    pub fn max_bytes(mut self, n: u64) -> Self {
68	        self.max_bytes = Some(n);
69	        self
70	    }
71	
72	    /// Set the item ceiling.
73	    #[must_use]
74	    pub fn max_items(mut self, n: u64) -> Self {
75	        self.max_items = Some(n);
76	        self
77	    }
78	
79	    /// Set the tokens the response cost.
80	    #[must_use]
81	    pub fn tokens_used(mut self, n: u64) -> Self {
82	        self.tokens_used = Some(n);
83	        self
84	    }
85	
86	    /// Set the bytes the response cost.
87	    #[must_use]
88	    pub fn bytes_used(mut self, n: u64) -> Self {
89	        self.bytes_used = Some(n);
90	        self
91	    }
92	
93	    /// Set whether the budget dropped something the sections cannot show (a section left out entirely). A cut a
94	    /// section reports through its own total needs no call: it makes the rendered `truncated` true by itself.
95	    #[must_use]
96	    pub fn truncated(mut self, truncated: bool) -> Self {
97	        self.truncated = truncated;
98	        self
99	    }
100	}
101	
102	/// The `truncated` value a budget renders: the caller's flag, or any section that was cut.
103	fn rendered_truncated(b: &BudgetSummary, sections: &[Section]) -> bool {
104	    b.truncated || sections.iter().any(Section::truncated)
105	}
106	
107	/// Render the `budget:` block, with no trailing newline. With two or more `sections`, the
108	/// `sections[n]{name,returned,total,truncated}:` roll-up of those sections follows. An unknown `total` is the TOON
109	/// `null` cell, because a table row needs a value in every column.
110	pub(crate) fn render_budget_block(b: &BudgetSummary, sections: &[Section]) -> String {
111	    let mut out = String::with_capacity(160 + sections.len() * 48);
112	    out.push_str("budget:");
113	    for (key, value) in numbers(b) {
114	        if let Some(n) = value {
115	            let _ = write!(out, "\n  {key}: {n}");
116	        }
117	    }
118	    let _ = write!(out, "\n  truncated: {}", rendered_truncated(b, sections));
119	    if sections.len() >= 2 {
120	        table::push_header(&mut out, "sections", sections.len(), ["name", "returned", "total", "truncated"]);
121	        for s in sections {
122	            let cells =
123	                [Cell::Str(s.name()), Cell::count(s.count()), Cell::opt_count(s.total()), Cell::Bool(s.truncated())];
124	            table::push_row(&mut out, &cells);
125	        }
126	    }
127	    out
128	}
129	
130	/// The optional counters in render order.
131	fn numbers(b: &BudgetSummary) -> [(&'static str, Option<u64>); 5] {
132	    [
133	        ("tokensUsed", b.tokens_used),
134	        ("bytesUsed", b.bytes_used),
135	        ("maxTokens", b.max_tokens),
136	        ("maxBytes", b.max_bytes),
137	        ("maxItems", b.max_items),
138	    ]
139	}
140	
141	/// Append the budget as a JSON object with camelCase keys; absent numbers are omitted. There is no per-section list:
142	/// the response's own `sections` array carries each section's counts.
143	pub(crate) fn push_budget_json(out: &mut String, b: &BudgetSummary, sections: &[Section]) {
144	    out.push('{');
145	    for (key, value) in numbers(b) {
146	        if let Some(n) = value {
147	            let _ = write!(out, "\"{key}\":{n},");
148	        }
149	    }
150	    out.push_str("\"truncated\":");
151	    crate::json::push_bool(out, rendered_truncated(b, sections));
152	    out.push('}');
153	}
154	
155	#[cfg(test)]
156	mod tests {
157	    use super::*;
158	    use crate::toon::Value;
159	
160	    fn spec_example() -> BudgetSummary {
161	        BudgetSummary::new().tokens_used(7412).bytes_used(31208).max_tokens(8000).max_bytes(2_097_152)
162	    }
163	
164	    /// The two sections of spec 07's example: 12 of 40 symbols, all 5 refs.
165	    fn spec_sections() -> Vec<Section> {
166	        let rows = |n| vec![vec![Value::Int(1)]; n];
167	        vec![
168	            Section::toon("brief.symbols", vec!["n".into()], rows(12)).total_count(Some(40)),
169	            Section::toon("brief.refs", vec!["n".into()], rows(5)).total_count(Some(5)),
170	        ]
171	    }
172	
173	    fn json(b: &BudgetSummary, sections: &[Section]) -> String {
174	        let mut out = String::new();
175	        push_budget_json(&mut out, b, sections);
176	        out
177	    }
178	
179	    const SPEC_BLOCK: &str =
180	        "budget:\n  tokensUsed: 7412\n  bytesUsed: 31208\n  maxTokens: 8000\n  maxBytes: 2097152\n  truncated: true";
181	    const SPEC_ROLLUP: &str =
182	        "\nsections[2]{name,returned,total,truncated}:\n  brief.symbols,12,40,true\n  brief.refs,5,5,false";
183	
184	    #[test]
185	    fn spec_example_renders_exactly_with_rollup() {
186	        assert_eq!(render_budget_block(&spec_example(), &spec_sections()), format!("{SPEC_BLOCK}{SPEC_ROLLUP}"));
187	    }
188	
189	    #[test]
190	    fn rollup_only_with_two_or_more_sections() {
191	        assert_eq!(render_budget_block(&spec_example(), &spec_sections()[..1]), SPEC_BLOCK);
192	    }
193	
194	    #[test]
195	    fn absent_fields_are_omitted_not_null() {
196	        let b = BudgetSummary::new().tokens_used(10).max_items(3);
197	        let out = render_budget_block(&b, &[]);
198	        assert_eq!(out, "budget:\n  tokensUsed: 10\n  maxItems: 3\n  truncated: false");
199	        assert!(!out.contains("null"));
200	        assert_eq!(render_budget_block(&BudgetSummary::new(), &[]), "budget:\n  truncated: false");
201	    }
202	
203	    #[test]
204	    fn unknown_total_is_a_null_cell_and_hostile_names_are_quoted() {
205	        let sections = [Section::kv("a,b\nbudget: x", vec![]), Section::text("n", "x")];
206	        let out = render_budget_block(&BudgetSummary::new(), &sections);
207	        assert_eq!(
208	            out,
209	            "budget:\n  truncated: false\nsections[2]{name,returned,total,truncated}:\n  \"a,b\\nbudget: x\",0,null,false\n  \
210	             n,1,null,false"
211	        );
212	        assert_eq!(out.lines().count(), 5, "no fake lines");
213	    }
214	
215	    #[test]
216	    fn json_matches_spec_shape() {
